from fastapi.sse import ServerSentEvent, format_sse_event
import pytest

def test_sse_validation():
    # Test ServerSentEvent model
    try:
        ServerSentEvent(event="line1\nline2", data="hello")
    except ValueError as e:
        assert str(e) == "SSE 'event' must not contain newlines"
    else:
        pytest.fail("Should have raised ValueError for event with newline")

    try:
        ServerSentEvent(id="line1\nline2", data="hello")
    except ValueError as e:
        assert str(e) == "SSE 'id' must not contain newlines"
    else:
        pytest.fail("Should have raised ValueError for id with newline")

    # Test format_sse_event function
    try:
        format_sse_event(data_str="hello", event="line1\nline2")
    except ValueError as e:
        assert str(e) == "SSE 'event' must not contain newlines"
    else:
        pytest.fail("Should have raised ValueError for event with newline in format_sse_event")

    try:
        format_sse_event(data_str="hello", id="line1\nline2")
    except ValueError as e:
        assert str(e) == "SSE 'id' must not contain newlines"
    else:
        pytest.fail("Should have raised ValueError for id with newline in format_sse_event")

    # Test valid cases
    assert format_sse_event(data_str="hello", event="test_event") == b"event: test_event\ndata: \"hello\"\n\n"
    assert format_sse_event(data_str="hello", id="test_id") == b"id: test_id\ndata: \"hello\"\n\n"
    assert ServerSentEvent(event="test_event", data="hello").model_dump() == {"data": "hello", "raw_data": None, "event": "test_event", "id": None, "retry": None, "comment": None}

if __name__ == "__main__":
    test_sse_validation()
    print("All tests passed!")
